def compute(vars):
    capitalized_interest_2018 = vars["v1"]
    capitalized_interest_2019 = vars["v2"]
    total_capitalized_interest = capitalized_interest_2018 + capitalized_interest_2019

    return {
        "value": total_capitalized_interest,
        "trace": {
            "capitalized_interest_2018": capitalized_interest_2018,
            "capitalized_interest_2019": capitalized_interest_2019,
            "output_meta": {
                "currency": "USD",
                "scale": "millions",
                "unit": "currency"
            }
        }
    }
